INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('d5460145-b49a-4ed2-8257-2b6627f3860b', 'Prepaid Vanilla Visa/Mastercard Gift Card - (up to 20% No-Rollover Bonus + Fees)', 'deposit', 'Vanilla Visa and Mastercard prepaid cards are non-reloadable gift/debit cards that function like debit cards but are not linked to a bank account. They are pre-loaded with a set amount of funds and can be used for in-store or online purchases wherever the respective card network (Visa or Mastercard) is accepted.
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('bc7035ee-9995-4624-9aa3-696a55659e3d', 'Amazon Gift Cards - (10% No-Rollover Bonus + Fees)', 'deposit', 'Amazon gift cards are prepaid instruments that add a balance to an Amazon account, allowing users to purchase millions of items across the platform. They are widely used for personal shopping and as versatile gifts for various occasions.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1773390181788-amazon.jpg', TRUE, FALSE, '8bcd74e0-f9a5-4b81-a65b-7b52f1b064cc', '2026-03-13T08:23:53.428Z', '2026-04-06T18:52:06.658Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('811abdc9-077c-4a89-a13d-b3237666f980', 'Amazon Gift Cards - (Free Payout up to $1,000/wk)', 'payout', 'FREE PAYOUT METHOD
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('32d7b230-7049-40f3-b72e-4f563f2091cc', 'Money Orders - ($75 charge up to $1,000/wk)', 'payout', NULL, 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1775320693451-MoneyOrder.jfif', FALSE, FALSE, '8bcd74e0-f9a5-4b81-a65b-7b52f1b064cc', '2026-03-13T08:29:12.568Z', '2026-04-06T18:48:19.104Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('6522a18b-a9a0-4928-b810-2382a0eb934c', 'Paypal to Paypal - (10% No-Rollover Bonus + Fees)', 'deposit', 'Paypal is an electronic commerce (e-commerce) company that facilitates payments between parties through online funds transfers. PayPal allows customers to establish an account on its website, which is connected to a user''s credit card or checking account.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1773510713133-paypal.jpg', TRUE, FALSE, '23986a0b-6417-4059-9a9a-6b1ffeb92b56', '2026-03-14T17:56:55.612Z', '2026-04-06T18:49:38.384Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('9064661d-965f-40b1-aea3-d9609c84ae3c', 'Remitly - (10% No-Rollover Bonus + Fees)', 'deposit', 'Remitly is a digital-first international money transfer service that allows users to send funds to over 170 countries in more than 100 currencies. Founded in 2011 and based in Seattle, it specializes in helping immigrants send money to friends and family through a mobile app or website, bypassing traditional physical bank branches.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1775140242760-Remitly.png', TRUE, FALSE, 'a29b6e8c-b5b4-46ed-9e7d-040d9262cd2b', '2026-03-19T16:18:49.717Z', '2026-04-06T18:49:53.816Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('c53419df-67b4-4a24-bdf4-44099d771db8', 'Venmo - (10% No-Rollover Bonus - + Fees)', 'deposit', 'Venmo is a popular U.S.-based mobile payment service owned by PayPal, designed for fast, social, and secure money transfers between friends, family, and authorized businesses. Users can split bills, make purchases using a linked bank account/card or app balance, and pay via QR codes, all while sharing transaction notes on a social feed.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1774912357209-Venmo.jfif', TRUE, FALSE, 'e521fd0c-7cf7-4e10-8458-300aea934d5d', '2026-03-30T23:10:20.034Z', '2026-04-06T18:50:07.906Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('0968a737-3e25-4932-827b-8f812e9b23ad', 'Zelle Pay - (10% No-Rollover Bonus - + Fees)', 'deposit', 'Zelle is a fast, secure, and free digital payment service in the U.S. that allows you to send and receive money directly between bank accounts, usually within minutes. It is designed for transactions with friends, family, and trusted small businesses, using only a U.S. mobile number or email address. 
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('01b9ebde-7c33-47e2-a2a1-bacb954c64c3', 'Cash App - (10% No-Rollover Bonus + Fees)', 'deposit', 'Cash App is a popular financial platform developed by Block, Inc. (formerly Square) that allows users to send, receive, and manage money instantly. It offers peer-to-peer payments, a customizable debit card ("Cash Card"), stock/bitcoin investing, and banking features like direct deposit. It is not a bank, but provides services through bank partners.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1774912616719-Cash%20App.png', TRUE, FALSE, 'e521fd0c-7cf7-4e10-8458-300aea934d5d', '2026-03-30T23:10:50.937Z', '2026-04-06T18:50:38.203Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('1ba09487-537b-4575-b497-051c8dac9cd1', 'Bitcoin - (BTC) - (20% No-Rollover Bonus + Fees)', 'deposit', 'Bitcoin (BTC) is the first decentralized, peer-to-peer digital currency and payment network, launched in 2009 by the anonymous creator Satoshi Nakamoto. It operates without a central authority or bank, using blockchain technology to securely record transactions across a distributed network. Only 21 million bitcoins will ever exist.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1774912681564-BTC.jfif', TRUE, FALSE, 'e521fd0c-7cf7-4e10-8458-300aea934d5d', '2026-03-30T23:11:11.324Z', '2026-04-06T18:50:57.852Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('17bab81c-000b-4877-9508-3b691751e9e1', 'Ethereum - (ETH) - (20% No-Rollover Bonus + Fees)', 'deposit', 'Ethereum is a decentralized, open-source blockchain platform that enables the creation and execution of smart contracts and decentralized applications (dApps). Launched in 2015 by Vitalik Buterin and other co-founders, it is currently the second-largest cryptocurrency by market capitalization.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1774912760518-ETH.png', TRUE, FALSE, 'e521fd0c-7cf7-4e10-8458-300aea934d5d', '2026-03-30T23:11:22.246Z', '2026-04-06T18:51:12.946Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('c7a9c4be-0418-401b-bb4e-bf957a4bcb9b', 'Money Orders', 'deposit', NULL, 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1775088392550-MoneyOrder.jfif', FALSE, FALSE, 'e521fd0c-7cf7-4e10-8458-300aea934d5d', '2026-04-02T00:01:17.293Z', '2026-04-02T14:29:34.434Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('a111fbec-04d1-4835-8083-02ad8e5326f1', 'WISE - (10% No-Rollover Bonus - + Fees)', 'deposit', 'Wise (formerly TransferWise) is a London-based fintech company providing fast, low-cost international money transfers and multi-currency accounts. It uses the real mid-market exchange rate (no markup) and charges small, transparent upfront fees. It is widely used by individuals and businesses for cheaper, faster global payments compared to traditional banks.', 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1775142469595-WISE.jfif', FALSE, FALSE, 'e521fd0c-7cf7-4e10-8458-300aea934d5d', '2026-04-02T15:07:54.550Z', '2026-04-06T21:39:34.813Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
INSERT INTO "payment_methods" ("id", "name", "type", "description", "logo_url", "is_active", "is_deleted", "created_by_admin_id", "created_at", "updated_at", "cashier_id") VALUES ('6dcc24d0-69e0-46ae-bfa2-c78e9a2411fe', 'Paypal to Paypal - ($50 charge up to $1,000/wk)', 'payout', NULL, 'https://mgkaxyqe7apdehaq.public.blob.vercel-storage.com/method-logos/1775500608596-1773510713133-paypal.webp', FALSE, FALSE, '28cb1dbd-5bf0-4743-a869-5578863c2c3f', '2026-04-06T18:00:26.067Z', '2026-04-06T18:48:19.660Z', 'a1b2c3d4-e5f6-7890-abcd-ef1234567890');
